//! THTML generation. Every piece of page-derived text goes through `textsafe`; every
//! attribute value is either a constant, a number, a hex id generated by us, or
//! `attr_text`-sanitised alt text. No URL or path from a page is ever emitted.

use crate::config::Config;
use crate::model::{Block, LocalImage, Page};
use crate::textsafe::{attr_text, clean_text, clickable_label, escape_text, shorten_long_tokens, truncate_cols};

/// Geometry of one variant.
#[derive(Debug, Clone, Copy)]
pub struct Geometry {
    /// Root width in cells.
    pub total: u16,
    /// Text column width in cells.
    pub cols: u16,
}

impl Geometry {
    /// Desktop (80 columns): the configured column, centred.
    pub fn desktop(cfg: &Config) -> Self {
        Geometry { total: 80, cols: cfg.content_cols.min(76) }
    }
    /// Mobile (40 columns).
    pub fn mobile() -> Self {
        Geometry { total: 40, cols: 36 }
    }
    fn pad(&self) -> u16 {
        (self.total - self.cols) / 2
    }
}

fn style_block(g: Geometry) -> String {
    let c = g.cols;
    let c2 = c.saturating_sub(2);
    let c3 = c.saturating_sub(3);
    format!(
        "<style>\n\
.h1 {{ fg: #fbbf24; wrap: word; width: {c}; margin-top: 1; margin-bottom: 1; }}\n\
.h2 {{ fg: #38bdf8; wrap: word; width: {c}; margin-top: 1; margin-bottom: 1; }}\n\
.h3 {{ fg: #4ade80; wrap: word; width: {c}; margin-bottom: 1; }}\n\
.p {{ fg: #e2e8f0; wrap: word; width: {c}; margin-bottom: 1; }}\n\
.q {{ fg: #94a3b8; wrap: word; width: {c2}; margin-left: 2; margin-bottom: 1; }}\n\
.li {{ fg: #e2e8f0; wrap: word; width: {c2}; margin-left: 2; }}\n\
.list {{ flex-direction: column; margin-bottom: 1; }}\n\
.code {{ bg: #1e293b; width: {c}; flex-direction: column; padding-left: 1; margin-bottom: 1; }}\n\
.cl {{ fg: #a7f3d0; height: 1; }}\n\
.link {{ fg: #38bdf8; height: 1; width: {c}; }}\n\
.note {{ fg: #64748b; wrap: word; width: {c3}; margin-left: 3; margin-bottom: 1; }}\n\
.muted {{ fg: #64748b; wrap: word; width: {c}; }}\n\
.alt {{ fg: #64748b; wrap: word; width: {c}; margin-bottom: 1; }}\n\
.status {{ fg: #fbbf24; wrap: word; width: {c}; }}\n\
.rule {{ fg: #334155; height: 1; margin-bottom: 1; }}\n\
.bar {{ height: 3; bg: #1e293b; border-style: single; border-color: #334155; align-items: center; padding-left: 1; padding-right: 1; }}\n\
.back {{ fg: #38bdf8; height: 1; margin-right: 2; }}\n\
</style>\n"
    )
}

fn text(class: &str, content: &str) -> String {
    format!("<text class=\"{class}\">{}</text>\n", escape_text(content))
}

fn safe_para(s: &str) -> String {
    shorten_long_tokens(&clean_text(s), 60)
}

/// Resizes a stored image's cell box to a (possibly narrower) column.
fn fit_image(img: &LocalImage, max_cols: u16) -> (u16, u16) {
    if img.cols <= max_cols {
        return (img.cols, img.rows);
    }
    let rows = ((img.rows as f64) * (max_cols as f64) / (img.cols as f64)).round().max(1.0) as u16;
    (max_cols, rows)
}

fn render_block(b: &Block, g: Geometry, out: &mut String) {
    let c = g.cols as usize;
    match b {
        Block::Heading(level, t) => {
            out.push_str(&text(&format!("h{}", (*level).clamp(1, 3)), &safe_para(t)));
        }
        Block::Para(t) => out.push_str(&text("p", &safe_para(t))),
        Block::List { ordered, items } => {
            out.push_str("<box class=\"list\">\n");
            for (i, it) in items.iter().enumerate() {
                let prefix = if *ordered { format!("{}. ", i + 1) } else { "- ".to_string() };
                out.push_str(&text("li", &format!("{prefix}{}", safe_para(it))));
            }
            out.push_str("</box>\n");
        }
        Block::Quote(t) => out.push_str(&text("q", &format!("> {}", safe_para(t)))),
        Block::Code(lines) => {
            out.push_str("<box class=\"code\">\n");
            for l in lines {
                let indent = l.len() - l.trim_start().len();
                let indent = indent.min(c / 2);
                let body = truncate_cols(l.trim(), c.saturating_sub(2 + indent));
                // The parser trims text nodes, so indentation is a margin, not spaces.
                out.push_str(&format!("<text class=\"cl\" style=\"margin-left: {indent};\">{}</text>\n", escape_text(&body)));
            }
            out.push_str("</box>\n");
        }
        Block::Image { alt, local: Some(img), .. } => {
            let (w, h) = fit_image(img, g.cols);
            out.push_str(&format!(
                "<img src=\"{}\" alt=\"{}\" style=\"width: {w}; height: {h}; margin-bottom: 1;\"/>\n",
                img.file,
                attr_text(alt, 100)
            ));
            let cap = clean_text(alt);
            if !cap.is_empty() {
                // Caption sits right under the image: tighten the image margin by omitting it.
                out.push_str(&text("alt", &truncate_cols(&cap, c * 2)));
            }
        }
        Block::Image { alt, local: None, .. } => {
            let cap = clean_text(alt);
            out.push_str(&text("alt", &format!("[image{}]", if cap.is_empty() { String::new() } else { format!(": {cap}") })));
        }
        Block::Rule => out.push_str(&format!("<text class=\"rule\">{}</text>\n", "-".repeat(c.min(40)))),
    }
}

/// Renders a page for one geometry. `id` is the page id used in link actions.
pub fn render_page(page: &Page, id: &str, g: Geometry) -> String {
    let c = g.cols as usize;
    let mut o = String::new();
    o.push_str(&style_block(g));
    o.push_str(&format!("<box style=\"flex-direction: column; width: {};\">\n", g.total));
    // Header bar: 3 rows (border 2 + 1 text row).
    let title_cols = (g.total as usize).saturating_sub(2 + 2 + 6 + 2 + 1);
    o.push_str("<box class=\"bar\">\n<text class=\"back\" event-htmx=\"go_home\">&lt; Back</text>\n");
    o.push_str(&format!(
        "<text style=\"fg: #f8fafc; height: 1;\">{}</text>\n</box>\n",
        escape_text(&truncate_cols(&clean_text(&page.title), title_cols))
    ));
    o.push_str(&format!(
        "<box style=\"flex-direction: column; padding-left: {p}; padding-right: {p}; padding-top: 1; padding-bottom: 1; width: {t};\">\n",
        p = g.pad(),
        t = g.total
    ));
    // Errors of actions started from this page (expired link, rate limit, refused host...).
    o.push_str(&format!("<text class=\"status\" bind-state=\"status\"/>\n"));
    if !page.list_mode {
        o.push_str(&text("h1", &truncate_cols(&safe_para(&page.title), c * 3)));
    }
    if let Some(m) = &page.meta {
        o.push_str(&text("muted", &safe_para(m)));
    }
    if page.source_url.is_some() {
        o.push_str(&format!(
            "<text class=\"link\" bind-show=\"_is_web=true\" style=\"margin-top: 1;\" event-htmx=\"open_original:{id}\">Open original in browser</text>\n"
        ));
    }
    o.push_str("<text class=\"muted\"> </text>\n");
    for b in &page.blocks {
        render_block(b, g, &mut o);
    }
    if !page.links.entries.is_empty() {
        if !page.list_mode || !page.blocks.is_empty() {
            o.push_str(&text("h2", &page.links_title));
        }
        for (i, e) in page.links.entries.iter().enumerate() {
            let n = i + 1;
            let prefix = if page.list_mode { format!("{n}. ") } else { format!("[{n}] ") };
            let host = if page.list_mode { String::new() } else { link_host(&e.target) };
            // host is ASCII (punycode) but run it through the same filter for uniformity.
            let host = if host.is_empty() { String::new() } else { clickable_label(&host, 40) };
            let host_part = if host.is_empty() { String::new() } else { format!("  {host}") };
            let room = c.saturating_sub(prefix.len() + host_part.len());
            let label = clickable_label(&e.label, room.max(8));
            let line = format!("{prefix}{label}{host_part}");
            o.push_str(&format!("<text class=\"link\" event-htmx=\"open_link:{id}.{n}\">{}</text>\n", escape_text(&truncate_cols(&line, c))));
            if let Some(note) = &e.note {
                let note = safe_para(note);
                if !note.is_empty() {
                    o.push_str(&text("note", &truncate_cols(&note, c * 2)));
                    continue;
                }
            }
            if page.list_mode {
                o.push_str("<text class=\"muted\"> </text>\n");
            }
        }
    }
    o.push_str("</box>\n</box>\n");
    o
}

fn link_host(t: &crate::model::LinkTarget) -> String {
    match t {
        crate::model::LinkTarget::Url(u) => url::Url::parse(u).ok().and_then(|u| u.host_str().map(str::to_string)).unwrap_or_default(),
        crate::model::LinkTarget::Wiki { lang, .. } => format!("{lang}.wikipedia.org"),
        crate::model::LinkTarget::HnStory(_) => "news.ycombinator.com".to_string(),
    }
}

/// The start page. Desktop: one 80x24 screen; mobile: a 40-column scrolling column.
pub fn render_index(cfg: &Config, mobile: bool) -> String {
    let feeds: Vec<String> = cfg
        .feeds
        .iter()
        .enumerate()
        .map(|(i, f)| {
            let label = clickable_label(&f.name, if mobile { 30 } else { 14 });
            let w = if mobile { 36 } else { 18 };
            format!(
                "<box class=\"btn\" style=\"width: {w}; border-color: #c084fc;\" event-htmx=\"rss:{i}\"><text style=\"fg: #c084fc; height: 1;\">{}</text></box>\n",
                escape_text(&label)
            )
        })
        .take(if mobile { 6 } else { 4 })
        .collect();
    let feeds = feeds.join("");
    let tpl = if mobile { include_str!("../templates/index_mobile.thtml") } else { include_str!("../templates/index.thtml") };
    tpl.replace("{{FEEDS}}", &feeds)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{LinkTable, LinkTarget};

    pub fn sample_page() -> Page {
        let mut p = Page::new("A <b>\"Title\"</b> & more");
        p.meta = Some("by <me> - example.com".into());
        p.source_url = Some("https://example.com/a".into());
        p.blocks = vec![
            Block::Heading(1, "Head <script>".into()),
            Block::Para("Para with & < > \" ' and a [1] marker. https://example.com/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".into()),
            Block::List { ordered: true, items: vec!["one".into(), "two <i>".into()] },
            Block::Quote("quote".into()),
            Block::Code(vec!["fn main() {".into(), "    x();".into(), "}".into(), "".into()]),
            Block::Image { src: "https://e.com/i.png".into(), alt: "a \"quoted\" <alt>".into(), local: Some(LocalImage { file: "ab12.png".into(), cols: 40, rows: 10 }) },
            Block::Image { src: String::new(), alt: "svg logo".into(), local: None },
            Block::Rule,
        ];
        let mut t = LinkTable::default();
        t.add(LinkTarget::Url("https://example.com/x".into()), "Next \u{2192} page \u{00D7}", None);
        p.links = t;
        p
    }

    #[test]
    fn page_has_escaped_text_and_opaque_actions_only() {
        let id = "0123456789abcdef0123456789abcdef";
        let s = render_page(&sample_page(), id, Geometry::desktop(&Config::default()));
        assert!(!s.contains("<script"), "{s}");
        assert!(s.contains("&lt;script&gt;"));
        assert!(s.contains(&format!("event-htmx=\"open_link:{id}.1\"")));
        assert!(s.contains("event-htmx=\"go_home\"") && s.contains("bind-state=\"status\""));
        assert!(!s.contains("https://example.com/x"), "link URLs must stay server-side");
        assert!(s.contains("src=\"ab12.png\""));
        assert!(!s.contains('\u{2192}') && !s.contains('\u{00D7}'));
        assert!(s.contains("[1] Next ? page ?  example.com<"), "label and host stay separated: {s}");
        assert!(s.contains("wrap: word"));
        assert!(s.contains("margin-left: 4;"), "code indentation as margin");
    }

    #[test]
    fn index_pages_render_with_feeds() {
        let c = Config::default();
        for m in [false, true] {
            let s = render_index(&c, m);
            assert!(!s.contains("{{FEEDS}}"));
            assert!(s.contains("event-htmx=\"rss:0\"") && s.contains("event-htmx=\"hn_top\"") && s.contains("event-htmx=\"fetch_url\""));
        }
    }
}
